6 static const char* DecodeArmImplementer( uint32_t v )
7 {
8     static char buf[16];
9     switch( v )
10     {
11     case 0x41: return "ARM";
12     case 0x42: return "Broadcom";
13     case 0x43: return "Cavium";
14     case 0x44: return "DEC";
15     case 0x46: return "Fujitsu";
16     case 0x48: return "HiSilicon";
17     case 0x49: return "Infineon";
18     case 0x4d: return "Motorola";
19     case 0x4e: return "Nvidia";
20     case 0x50: return "Applied Micro";
21     case 0x51: return "Qualcomm";
22     case 0x53: return "Samsung";
23     case 0x54: return "Texas Instruments";
24     case 0x56: return "Marvell";
25     case 0x61: return "Apple";
26     case 0x66: return "Faraday";
27     case 0x68: return "HXT";
28     case 0x69: return "Intel";
29     case 0xc0: return "Ampere Computing";
30     default: break;
31     }
32     sprintf( buf, "0x%x", v );
33     return buf;
34 }
